import assert from 'node:assert/strict';
import test from 'node:test';
import { createApp } from '../../app.js';

function appFor(lines) {
  return createApp({ invoices: { async load() { return { lines }; } } });
}

test('invoice totals use the injected repository and preserve profile behavior', async () => {
  const app = createApp({
    invoices: { async load(id) {
      assert.equal(id, 'invoice-7');
      return { lines: [
        { quantity: 3, unitPriceCents: 125 },
        { quantity: 2, unitPriceCents: 249 },
      ] };
    } },
    profile: { async load(id) {
      assert.equal(id, 'account-1');
      return { displayName: '  Ada  ' };
    } },
  });
  assert.equal(await app.invoices.total('invoice-7'), 873);
  assert.equal(await app.profile.label('account-1'), 'Ada');
});

test('empty invoices and zero quantities or prices total zero', async () => {
  assert.equal(await appFor([]).invoices.total('empty'), 0);
  assert.equal(await appFor([
    { quantity: 0, unitPriceCents: 100 },
    { quantity: 2, unitPriceCents: 0 },
  ]).invoices.total('zero'), 0);
});

test('rejects invalid quantities and prices, including on zero-valued lines', async () => {
  for (const field of ['quantity', 'unitPriceCents']) {
    for (const value of [-1, 0.5, NaN, Infinity, '2', null, undefined]) {
      const line = { quantity: 0, unitPriceCents: 0, [field]: value };
      await assert.rejects(appFor([line]).invoices.total('invalid'), TypeError);
    }
  }
});

test('repository failures reach the caller', async () => {
  const failure = new Error('load failed');
  const app = createApp({ invoices: { async load() { throw failure; } } });
  await assert.rejects(app.invoices.total('missing'), (error) => error === failure);
});

