export function invoiceTotal(invoice) {
  return invoice.lines.reduce((total, { quantity, unitPriceCents }) => {
    if (!Number.isInteger(quantity) || quantity < 0 ||
        !Number.isInteger(unitPriceCents) || unitPriceCents < 0) {
      throw new TypeError('Invoice quantities and prices must be nonnegative integers');
    }
    return total + quantity * unitPriceCents;
  }, 0);
}

